content.content:
import { Component, computed, input, model } from '@angular/core';

@Component({
  selector: 'app-filter-bar',
  imports: [],
  templateUrl: './filter-bar.html',
  styleUrl: './filter-bar.scss'
})
export class FilterBar {
  readonly von = model<string | null>(null);
  readonly bis = model<string | null>(null);
  readonly spielstaetteId = model<string | null>(null);

  readonly spielstaetten = input<{ id: string; name: string }[]>([]);

  protected readonly filterAktiv = computed(
    () => this.von() !== null || this.bis() !== null || this.spielstaetteId() !== null
  );

  protected zuruecksetzen(): void {
    this.von.set(null);
    this.bis.set(null);
    this.spielstaetteId.set(null);
  }
}
---html---
<div class="filter-bar">
  <div class="filter-bar__feld">
    <label class="filter-bar__label" for="filter-bar-von">Von</label>
    <input
      id="filter-bar-von"
      class="filter-bar__input"
      type="date"
      [value]="von()"
      (change)="von.set($any($event.target).value || null)"
    />
  </div>

  <div class="filter-bar__feld">
    <label class="filter-bar__label" for="filter-bar-bis">Bis</label>
    <input
      id="filter-bar-bis"
      class="filter-bar__input"
      type="date"
      [value]="bis()"
      (change)="bis.set($any($event.target).value || null)"
    />
  </div>

  <div class="filter-bar__feld">
    <label class="filter-bar__label" for="filter-bar-spielstaette">Spielstätte</label>
    <select
      id="filter-bar-spielstaette"
      class="filter-bar__input"
      [value]="spielstaetteId() ?? ''"
      (change)="spielstaetteId.set($any($event.target).value || null)"
    >
      <option value="">Alle</option>
      @for (spielstaette of spielstaetten(); track spielstaette.id) {
        <option [value]="spielstaette.id">{{ spielstaette.name }}</option>
      }
    </select>
  </div>

  @if (filterAktiv()) {
    <button type="button" class="filter-bar__zuruecksetzen" (click)="zuruecksetzen()">Zurücksetzen</button>
  }
</div>

